// Named sound cues a message can use via `sound`. Pure data, shared by the
// validator and the audio mixer.
//
// kinds:
//   synth    - generated by an FFmpeg filter graph (original work, no license needed)
//   voice    - a spoken word from assets/sfx/voice/<file>, trimmed and normalized
//
// Every generated cue is normalized to the same peak level, then gainDb is applied in the mix.

export const CUES = Object.freeze({
  // Message pops and whooshes; used by sound: "auto"
  receive: {
    kind: 'synth', gainDb: -6, duration: 0.2,
    graph: "aevalsrc=exprs='0.6*sin(2*PI*(1250-700*t/0.16)*t)*exp(-t*26)|0.6*sin(2*PI*(1250-700*t/0.16)*t)*exp(-t*26)':s=44100:d=0.2",
  },
  send: {
    kind: 'synth', gainDb: -6, duration: 0.26,
    graph: 'anoisesrc=d=0.26:c=white:r=44100:a=1,highpass=f=900,lowpass=f=4500,afade=t=in:d=0.05,afade=t=out:st=0.12:d=0.14',
  },
  // Deep bass drop with a fast pitch fall. Original, in the spirit of the "vine boom" meme.
  boom: {
    kind: 'synth', gainDb: -3, duration: 1.6,
    graph: 'aevalsrc=exprs=sin(2*PI*(35*t+85*(1-exp(-12*t))/12))*exp(-4*t)|sin(2*PI*(35*t+85*(1-exp(-12*t))/12))*exp(-4*t):s=44100:d=1.6',
  },
  // Two-tone "notification" chime
  ding: {
    kind: 'synth', gainDb: -6, duration: 1.4,
    graph: 'aevalsrc=exprs=(sin(2*PI*1318*t)+0.5*sin(2*PI*1976*t))*exp(-3.5*t)*0.5|(sin(2*PI*1318*t)+0.5*sin(2*PI*1976*t))*exp(-3.5*t)*0.5:s=44100:d=1.4',
  },
  // Four falling notes with a wah-wah tail
  sad: {
    kind: 'synth', gainDb: -5, duration: 2.2,
    graph: [
      'sine=f=392:d=0.45,afade=t=out:st=0.3:d=0.15[n1]',
      'sine=f=349:d=0.45,afade=t=out:st=0.3:d=0.15[n2]',
      'sine=f=330:d=0.45,afade=t=out:st=0.3:d=0.15[n3]',
      'sine=f=311:d=1.0,afade=t=out:st=0.5:d=0.5[n4]',
      '[n1][n2][n3][n4]concat=n=4:v=0:a=1',
    ].join(';'),
  },
  // Two thumps, lub-dub, then a pause
  heartbeat: {
    kind: 'synth', gainDb: -4, duration: 1.5,
    graph: [
      'aevalsrc=sin(2*PI*55*t)*exp(-22*t):s=44100:d=0.4[t1]',
      'aevalsrc=0|0:s=44100:d=0.12[g1]',
      'aevalsrc=sin(2*PI*55*t)*exp(-22*t)*0.8:s=44100:d=0.4[t2]',
      'aevalsrc=0|0:s=44100:d=0.6[g2]',
      '[t1][g1][t2][g2]concat=n=4:v=0:a=1',
    ].join(';'),
  },
  // Spoken word, recorded with the platform TTS voice (voice-00) and committed as a source file
  bruh: { kind: 'voice', gainDb: -4, source: 'voice/bruh.mp3' },
  rizz: { kind: 'voice', gainDb: -4, source: 'voice/rizz.mp3' },
});

export const CUE_NAMES = Object.freeze(Object.keys(CUES));
/** Values allowed in message.sound (besides a cue name). */
export const SOUND_OPTIONS = Object.freeze(['auto', 'none']);
